package com.vynedam.stockai.service; import com.vynedam.stockai.dto.UserDtos.*; import com.vynedam.stockai.exception.ApiException; import com.vynedam.stockai.model.User; import com.vynedam.stockai.repository.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class UserAdminService{private final UserRepository users;private final WarehouseRepository warehouses;private final PasswordEncoder passwords;public UserAdminService(UserRepository u,WarehouseRepository w,PasswordEncoder p){users=u;warehouses=w;passwords=p;}public List<User>list(){return users.findAll();}public User create(UserCreateRequest r){if(users.existsByEmailIgnoreCase(r.email()))throw new ApiException(HttpStatus.CONFLICT,"DUPLICATE_RECORD","Email already registered");var u=new User();u.name=r.name();u.email=r.email().toLowerCase();u.passwordHash=passwords.encode(r.password());u.role=r.role();u.unitId=r.unitId();u.warehouseIds=verify(r.warehouseIds());return users.save(u);}public User update(String id,UserUpdateRequest r){var u=get(id);u.name=r.name();u.role=r.role();u.unitId=r.unitId();u.warehouseIds=verify(r.warehouseIds());return users.save(u);}public User active(String id,boolean active){var u=get(id);u.active=active;return users.save(u);}private User get(String id){return users.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","User not found"));}private Set<String>verify(Set<String> ids){var result=ids==null?new HashSet<String>():new HashSet<>(ids);for(var id:result)if(!warehouses.existsById(id))throw new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Warehouse not found: "+id);return result;}}
